from fractions import Fraction

def calculate_b_squared(a):
    if a == 2:
        return None # Division by zero

    a_frac = Fraction(a)

    # a^2
    a_squared = a_frac * a_frac

    # a / (a - 2)
    a_minus_2 = a_frac - 2
    if a_minus_2 == 0:
        return None
    term = a_frac / a_minus_2

    # b^2 = a^2 - term
    b_squared = a_squared - term
    return b_squared

