from fractions import Fraction
import math

def is_perfect_square(n):
    if n < 0:
        return False
    if n == 0:
        return True
    s = int(math.isqrt(n)) # math.isqrt is available in newer versions, safe fallback for older ones
    return s * s == n

def calculate_b_squared(a: Fraction):
    # b^2 = a^2 - a/(a-2)
    if a == 2:
        return None # Undefined

    a_squared = a * a

    a_over_a_minus_2 = a / (a - 2)

    b_squared = a_squared - a_over_a_minus_2
    return b_squared

test_a_values = [Fraction(3, 2), Fraction(5, 2), Fraction(7, 2)]
results = {}

for a in test_a_values:
    b_sq = calculate_b_squared(a)

    if b_sq is not None:
        # Check if b_sq (which is already reduced Fraction) is the square of a rational number.
        # This means both numerator and denominator must be perfect squares.
        numerator = b_sq.numerator
        denominator = b_sq.denominator

        is_sq_rational = is_perfect_square(numerator) and is_perfect_square(denominator)

        results[a] = {
            'b_squared': b_sq,
            'is_rational_square': is_sq_rational
        }

print("--- TEST RESULTS ---")
for a, res in results.items():
    print(f"a = {a}:")
    print(f"  b^2 = {res['b_squared']}")
    print(f"  b is rational? {'Yes' if res['is_rational_square'] else 'No'}")
